      >
        <PromptInputBody>
          <PromptInputTextarea
            aria-label="Message SupplyOS"
            placeholder="Message SupplyOS"
            value={value}
            onChange={(event) => onChange(event.currentTarget.value)}
          />
        </PromptInputBody>
        <PromptInputFooter>
          <PromptInputTools />
          <PromptInputSubmit
            disabled={sendDisabled}
            status={status}
            onStop={status === "streaming" ? onStop : undefined}
          >
            {status === "ready" ? (
              <ArrowUpIcon aria-hidden="true" />
            ) : undefined}
